{
  "themes": [
    {
      "cluster": 24,
      "name": "Battlefront Pre‑Order & Beta Access Issues",
      "description": "Customers report trouble accessing the Battlefront II beta or upgrading pre‑ordered copies, often due to region or platform restrictions."
    },
    {
      "cluster": 25,
      "name": "Dashboard Redesign Complaints",
      "description": "Users express frustration with the new dashboard layout, calling it cluttered, buggy, and requesting a return to the old interface."
    },
    {
      "cluster": 26,
      "name": "GamerTag Change Failures",
      "description": "Players who paid to change their Gamertag say the change didn’t occur or was altered without consent, and they seek refunds or fixes."
    },
    {
      "cluster": 27,
      "name": "NAT Type Connectivity Problems",
      "description": "Customers experience strict or failed NAT settings, UPnP errors, and party disconnections, asking how to open NAT or resolve Xbox Live network issues."
    },
    {
      "cluster": 28,
      "name": "Store Purchase and Selection Errors",
      "description": "Users cannot select or buy games in the store, encounter missing payment options, or see unresponsive store menus."
    },
    {
      "cluster": 29,
      "name": "Cross‑Region Gift Code Restrictions",
      "description": "Customers trying to gift or redeem games across different regions report codes being invalid or blocked due to regional locks."
    },
    {
      "cluster": 30,
      "name": "Sign‑In Failures and Grey Screens",
      "description": "Players are unable to log into their accounts, often seeing a grey screen or generic sign‑in errors."
    },
    {
      "cluster": 31,
      "name": "Account Email Recovery and Deletion Issues",
      "description": "Users have lost or mistyped the email linked to their Xbox account and need help recovering or permanently deleting the profile."
    },
    {
      "cluster": 32,
      "name": "Home Xbox Sharing Configuration Problems",
      "description": "Customers struggle to set or reset a Home Xbox, encountering errors that prevent game sharing between accounts."
    },
    {
      "cluster": 33,
      "name": "General Help Requests with Minimal Detail",
      "description": "Posts contain vague pleas for assistance without specific information, making the issue unclear."
    },
    {
      "cluster": 34,
      "name": "Code Redemption Failures",
      "description": "Players report that Xbox Live or Game Pass codes (e.g., $25, $50) won’t redeem, often receiving error messages."
    },
    {
      "cluster": 35,
      "name": "Frequent Sign‑Out and Login Error Codes",
      "description": "Users experience repeated sign‑outs or login attempts that return specific error codes, preventing access to Xbox Live."
    }
  ]
}
